using JTradeERP.Application.Common.Exceptions; using JTradeERP.Application.Common.Persistence; using MediatR;
namespace JTradeERP.Application.Features.Security.Administration.GetUserById;
public sealed record GetUserByIdQuery(Guid Id):IRequest<GetUserByIdResponse>; public sealed record GetUserByIdResponse(Guid Id,string UserName,string Email,bool IsActive,IReadOnlyCollection<string> Roles);
public sealed class GetUserByIdHandler(IApplicationDbContext db):IRequestHandler<GetUserByIdQuery,GetUserByIdResponse>{public Task<GetUserByIdResponse> Handle(GetUserByIdQuery r,CancellationToken ct){var u=db.Users.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("User was not found.");var roles=(from ur in db.UserRoles join role in db.Roles on ur.RoleId equals role.Id where ur.UserId==u.Id select role.Name).ToArray();return Task.FromResult(new GetUserByIdResponse(u.Id,u.UserName,u.Email,u.IsActive,roles));}}
public static class GetUserByIdEndpoint{public static void Map(IEndpointRouteBuilder e)=>e.MapGet("/users/{id:guid}",async(Guid id,ISender s,CancellationToken t)=>Results.Ok(await s.Send(new GetUserByIdQuery(id),t))).RequirePermission("Admin.Users.Manage",Capability.Full);}
